/** 文件说明：LLM 工具修复的上下文与处理器契约。 */
import { EntityId, Role, ToolName } from "../../../core/domain/model";
import { World } from "../../../core/domain/world";

/** 参数纠正规则上下文。 */
export interface CoerceContext {
  actorId: EntityId;
}

/** 参数纠正处理器签名。 */
export type CoerceHandler = (
  args: Record<string, unknown>,
  ctx: CoerceContext,
) => Record<string, unknown> | null;

/** 单个原生工具参数纠正包定义。 */
export interface ToolRepairPack {
  coerce: Partial<Record<ToolName, CoerceHandler>>;
}

/** 可行动目标提示上下文。 */
export interface TargetHintContext {
  modifierCandidates?: readonly EntityId[];
  modifierBonusCandidates?: readonly EntityId[];
  actorId: EntityId;
  day?: number;
  actorRole?: Role;
  abilityId?: string;
  debateTargetId?: number;
  allowedTools: ToolName[];
  world: World;
  roleCatalog?: import("../roles/catalog").RoleCatalog;
  sheriffCandidates?: readonly EntityId[];
  badgeCandidates?: readonly EntityId[];
  exileCandidates?: readonly EntityId[];
}

/** 目标提示注册器契约。 */
export interface TargetHintRegistry {
  buildActionableIdsHint(ctx: TargetHintContext): string | undefined;
}

/** 文件说明：LLM 参数纠正流程共用工具函数。 */

/** 将任意输入安全转换为 number 或 null。 */
export function numberOrNull(value: unknown): number | null {
  if (value === null || value === undefined) {
    return null;
  }
  const num = Number(value);
  return Number.isFinite(num) ? num : null;
}

/** 文件说明：定义通用原生工具参数纠正规则。 */
import { ToolRepairPack } from "../llm/contracts";
import { numberOrNull } from "../llm/helpers";

export const COMMON_LLM_REPAIR_PACK: ToolRepairPack = {
  coerce: {
    speak: (args) => ({ text: String(args.text ?? "") }),
    vote: (args) => {
      const abstain = Boolean(args.abstain);
      if (abstain) return { target_id: null, abstain: true };
      const target = numberOrNull(args.target_id);
      return target === null ? null : { target_id: target, abstain: false };
    },
  },
};

/** 文件说明：定义跨角色通用工具的 schema 与提示信息。 */
import { ToolSpec } from "../contracts";

/** 通用工具规格列表。 */
export const COMMON_TOOL_SPECS: ToolSpec[] = [
  {
    name: "write_note",
    parameters: {
      type: "object",
      properties: { text: { type: "string" } },
      required: ["text"],
      additionalProperties: false,
    },
    argHint: 'write_note args: {"text":"..."}',
    userPromptHintKey: "action.write_note.hint",
  },
  {
    name: "debate_vote",
    parameters: {
      type: "object",
      properties: { support: { type: ["boolean", "null"] } },
      required: ["support"],
      additionalProperties: false,
    },
    argHint: 'debate_vote args: {"support":true|false|null}',
    userPromptHintKey: "action.debate_vote.hint",
  },
  {
    name: "report_bug",
    parameters: {
      type: "object",
      properties: {
        category: {
          type: "string",
          enum: ["flow", "rule", "state", "logging", "other"],
        },
        severity: {
          type: "string",
          enum: ["low", "medium", "high", "critical"],
        },
        message: { type: "string" },
      },
      required: ["category", "severity", "message"],
      additionalProperties: false,
    },
    argHint:
      'report_bug args: {"category":"flow|rule|state|logging|other","severity":"low|medium|high|critical","message":"..."}',
    userPromptHintKey: "action.report_bug.hint",
  },
  {
    name: "speak",
    parameters: {
      type: "object",
      properties: {
        text: { type: "string" },
      },
      required: ["text"],
      additionalProperties: false,
    },
    argHint: 'speak args: {"text":"..."}',
  },
  {
    name: "vote",
    parameters: {
      type: "object",
      properties: {
        target_id: { type: ["number", "null"] },
        abstain: { type: "boolean" },
      },
      required: ["target_id", "abstain"],
      additionalProperties: false,
    },
    argHint: 'vote args: {"target_id":number|null,"abstain":true|false}',
  },
];

/** 文件说明：板子配置规范化器契约。 */
import { BoardConfig } from "../../../core/domain/model";

/** 单个规范化器定义。 */
export interface ConfigNormalizer {
  id: string;
  normalize(config: BoardConfig): BoardConfig;
}

/** 文件说明：板子配置规范化注册表。 */
import { BoardConfig } from "../../../core/domain/model";
import { ConfigNormalizer } from "./contracts";
import { SHERIFF_CONFIG_NORMALIZER } from "../sheriff/config_normalizer";
import { WITCH_CONFIG_NORMALIZER } from "../roles/witch/config_normalizer";
import { SELF_DESTRUCT_CONFIG_NORMALIZER } from "../self_destruct/config_normalizer";

/** 默认配置规范化器顺序（从机制/角色模块聚合）。 */
const DEFAULT_NORMALIZERS: ConfigNormalizer[] = [
  WITCH_CONFIG_NORMALIZER,
  SHERIFF_CONFIG_NORMALIZER,
  SELF_DESTRUCT_CONFIG_NORMALIZER,
];

/** 配置规范化注册表。 */
export class ConfigNormalizerRegistry {
  constructor(private readonly normalizers: ConfigNormalizer[] = DEFAULT_NORMALIZERS) {}

  /** 按注册顺序依次执行规范化。 */
  normalize(config: BoardConfig): BoardConfig {
    return this.normalizers.reduce((current, normalizer) => normalizer.normalize(current), config);
  }
}

let defaultRegistry: ConfigNormalizerRegistry | null = null;

/** 获取默认规范化注册表。 */
export function getDefaultConfigNormalizerRegistry(): ConfigNormalizerRegistry {
  if (!defaultRegistry) {
    defaultRegistry = new ConfigNormalizerRegistry();
  }
  return defaultRegistry;
}

