/**
 * 负责聚合通用、警长与角色运行贡献的参数修复规则。输入为原修复包及回合上下文；
 * 输出为原 coercion 结果或原参数副本。注册保持顺序和最后处理函数引用；
 * 本索引不接受动作、消耗库存或授予当前请求权限。
 */
import { ToolName } from "../../../core/domain/model";
import { COMMON_LLM_REPAIR_PACK } from "../common/llm_repair";
import { RoleCatalog } from "../roles/catalog";
import { getDefaultRoleCatalog } from "../roles/role-catalog-assembly";
import { SHERIFF_LLM_REPAIR_PACK } from "../sheriff/llm_repair";
import { CoerceContext, ToolRepairPack } from "./contracts";

function buildDefaultPacks(roleProfileRegistry: RoleCatalog): ToolRepairPack[] {
  const packs: ToolRepairPack[] = [COMMON_LLM_REPAIR_PACK, SHERIFF_LLM_REPAIR_PACK];
  for (const { runtime: profile } of roleProfileRegistry.allRuntime()) {
    if (profile.llmRepair) {
      packs.push(profile.llmRepair);
    }
  }
  return packs;
}

/** LLM 工具调用修复注册表。 */
export class ToolCallRepairRegistry {
  private readonly coerceHandlers = new Map<ToolName, ToolRepairPack["coerce"][ToolName]>();

  constructor(
    packs?: ToolRepairPack[],
    roleProfileRegistry: RoleCatalog = getDefaultRoleCatalog(),
  ) {
    const effectivePacks = packs ?? buildDefaultPacks(roleProfileRegistry);
    for (const pack of effectivePacks) {
      for (const [name, handler] of Object.entries(pack.coerce)) {
        this.coerceHandlers.set(name as ToolName, handler);
      }
    }
  }

  coerceArgs(
    tool: ToolName,
    rawArgs: Record<string, unknown>,
    ctx: CoerceContext,
  ): Record<string, unknown> | null {
    const handler = this.coerceHandlers.get(tool);
    if (!handler) {
      return { ...rawArgs };
    }
    return handler(rawArgs, ctx);
  }
}

let defaultRegistry: ToolCallRepairRegistry | null = null;

/** 获取默认 LLM 工具调用修复注册表实例。 */
export function getDefaultToolCallRepairRegistry(): ToolCallRepairRegistry {
  if (!defaultRegistry) {
    defaultRegistry = new ToolCallRepairRegistry();
  }
  return defaultRegistry;
}

/**
 * 负责通用、警长和角色运行贡献的领域工具索引，以及有序本地化提示和指令。输入为原规格与指令数组；输出为同一规格和展示文字，不授予行动权限。重复的自有数据 schema 必须完全一致；兼容或不透明覆盖保留最后原引用与原文。参数 getter 和 schema 解析仍延迟至 ActionReception 首次使用；不合并 SDK／MCP 三项传输工具或写入领域状态。
 */
import { text, type Locale } from "@ai-werewolf-arena/game-text";
import { registerToolSpecs } from "../../../rulesets/tool-spec-registration";
import { ToolName } from "../../../core/domain/model";
import { COMMON_TOOL_SPECS } from "../common/tool_specs";
import { StageDirectiveRule, ToolSpec } from "../contracts";
import { RoleCatalog } from "../roles/catalog";
import { getDefaultRoleCatalog } from "../roles/role-catalog-assembly";
import { SHERIFF_TOOL_SPECS } from "../sheriff/tool_specs";

function buildDefaultSpecs(roleProfileRegistry: RoleCatalog): ToolSpec[] {
  const specs: ToolSpec[] = [...COMMON_TOOL_SPECS, ...SHERIFF_TOOL_SPECS];
  for (const { runtime: profile } of roleProfileRegistry.allRuntime()) {
    if (profile.toolSpecs) {
      specs.push(...profile.toolSpecs);
    }
  }
  return specs;
}

function buildDefaultStageDirectives(roleProfileRegistry: RoleCatalog): StageDirectiveRule[] {
  const directives: StageDirectiveRule[] = [];
  for (const { runtime: profile } of roleProfileRegistry.allRuntime()) {
    if (profile.stageDirectives) {
      directives.push(...profile.stageDirectives);
    }
  }
  return directives;
}

/** 工具规格注册表。 */
export class ToolSpecRegistry {
  private readonly specByName = new Map<ToolName, ToolSpec>();
  private readonly stageDirectives: StageDirectiveRule[];

  constructor(
    specs?: ToolSpec[],
    stageDirectives?: StageDirectiveRule[],
    roleProfileRegistry: RoleCatalog = getDefaultRoleCatalog(),
  ) {
    const effectiveSpecs = specs ?? buildDefaultSpecs(roleProfileRegistry);
    const effectiveDirectives = stageDirectives ?? buildDefaultStageDirectives(roleProfileRegistry);
    registerToolSpecs(this.specByName, effectiveSpecs);
    this.stageDirectives = [...effectiveDirectives];
  }

  get(name: ToolName): ToolSpec | undefined {
    return this.specByName.get(name);
  }

  getArgHint(name: ToolName): string | null {
    return this.specByName.get(name)?.argHint ?? null;
  }

  getUserPromptHint(name: ToolName, locale: Locale = "zh-CN"): string | null {
    const spec = this.specByName.get(name);
    return (
      spec?.userPromptHint ??
      (spec?.userPromptHintKey ? text(locale, spec.userPromptHintKey) : null)
    );
  }

  getStageDirective(allowedTools: ToolName[], locale: Locale = "zh-CN"): string | null {
    const matched = this.stageDirectives.find((rule) => rule.match(allowedTools));
    if (!matched) return null;
    // 调用方可以复制内建规则后覆盖原文；只在原文仍等于内建字节时采用对应翻译。
    return matched.messageKey && matched.text === text("zh-CN", matched.messageKey)
      ? text(locale, matched.messageKey)
      : matched.text;
  }

  getApplicableUserPromptHints(allowedTools: ToolName[], locale: Locale = "zh-CN"): string[] {
    return allowedTools
      .map((name) => this.getUserPromptHint(name, locale))
      .filter((item): item is string => Boolean(item));
  }
}

let defaultRegistry: ToolSpecRegistry | null = null;

/** 获取默认工具规格注册表实例。 */
export function getDefaultToolSpecRegistry(): ToolSpecRegistry {
  if (!defaultRegistry) {
    defaultRegistry = new ToolSpecRegistry();
  }
  return defaultRegistry;
}

/**
 * 负责完整行动接收预检：允许工具、首用 JSON schema、原参数修复、机制请求作用域和领域规则。
 * 输入为同一 World、原请求与外来工具参数；输出为脱离后的合法候选或原结构化拒绝。
 * 每实例只持有原 schema 缓存和不写第二 Tape 校验的 Gateway；schema 与具体 scope 仍按原时点晚读。
 * 本 owner 不消耗库存、提交领域动作或 settle 完成责任；选择／截止窗口由 AI ActionTurn 独立拥有。
 */
import { nobleBodyRequestScope } from "../mechanisms/roles/noble_secret_body/ports";
import { animalRequestScope } from "../mechanisms/roles/animal_dream/ports";
import { fragrantPairRequestScope } from "../mechanisms/roles/fragrant_pair_seer/ports";
import {
  demonWitchRequestTargetCurrent,
  demonWitchRequestCurrent,
  readDemonNativeNightTool,
  readDemonPotionTool,
} from "../mechanisms/roles/demon_hunter/ports";
import {
  demonHunterRequestScope,
  canSubmitDemonHunt,
  demonHunterActorId,
} from "../mechanisms/roles/demon_hunter/ports";
import { readDemonHuntTool } from "../mechanisms/roles/demon_hunter/ports";
import {
  ghostBrideRequestScope,
  weddingSetup,
} from "../mechanisms/roles/ghost_bride/ports";
import { readWeddingTool } from "@ai-werewolf-arena/game-contract/facts/ghost-bride";
import { lonelyGirlRequestScope } from "../mechanisms/roles/lonely_girl/ports";
import { readLonelyGirlTool } from "../mechanisms/roles/lonely_girl/ports";
import { wildChildRequestScope } from "../mechanisms/roles/wild_child/ports";
import { readWildChildTool } from "../mechanisms/roles/wild_child/ports";
import { shapeshifterRequestScope } from "../mechanisms/roles/shapeshifter/ports";
import { thiefRequestScope } from "../mechanisms/roles/thief/ports";
import { readThiefChoice } from "../mechanisms/roles/thief/ports";
import { wallRequestScope } from "../mechanisms/events/wall_notes/ports";
import { z, type ZodType } from "zod";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { toolFailure } from "@ai-werewolf-arena/game-text";
import { readWallTool } from "@ai-werewolf-arena/game-contract/facts/wall-notes";
import {
  DEATH_SHOT_STAGES,
  type ActionRequest,
  type ToolCall,
  type ToolName,
} from "../../core/domain";
import { World } from "../../core/domain/world";
import { ActionValidator } from "./action_validator";
import { ToolGateway } from "./tool_gateway";
import {
  getDefaultToolCallRepairRegistry,
  getDefaultToolValidationRuleRegistry,
  type ToolCallRepairRegistry,
  type ToolValidationRuleRegistry,
} from "../mechanisms";
import {
  getDefaultToolSpecRegistry,
  type ToolSpecRegistry,
} from "../mechanisms/registries/tool_spec_registry";
import { evaluateTurnConstraints, resolveTurnConstraints } from "./turn-constraints";
import type { Locale } from "@ai-werewolf-arena/game-contract";

/** 只描述预检结果，不表示领域已付款或生效；可选回合字段保留原拒绝结构接受集合。 */
export type GameActionValidation =
  | { ok: true; action: ToolCall }
  | {
      ok: false;
      error: string;
      message: string;
      details?: string[];
      expected_turn_id?: string;
      received_turn_id?: unknown;
    };

/**
 * 选择窗口的类型接口只声明原 locale 与预检函数，不提供写方法或领域完成接口。
 * 运行对象仍是原接收器和 World；这是消费契约，不是新的进程隔离或运行权限屏障。
 */
export interface ActionPreflightPort {
  readonly world: { readonly locale: Locale };
  validate(request: ActionRequest, name: string, rawArgs: unknown): GameActionValidation;
}
type Validation = GameActionValidation;

/** 预检只形成候选；实际应用与资源消费仍由引擎和具体机制提交。 */
export class ActionReception {
  private readonly schemas = new Map<ToolName, ZodType>();
  private readonly gateway: ToolGateway;

  constructor(
    readonly world: World,
    private readonly repair: ToolCallRepairRegistry = getDefaultToolCallRepairRegistry(),
    private readonly specs: ToolSpecRegistry = getDefaultToolSpecRegistry(),
    rules: ToolValidationRuleRegistry = getDefaultToolValidationRuleRegistry(),
  ) {
    // 这里仍关闭领域校验的 Tape 记录，避免接收预检制造第二次 validation 操作。
    this.gateway = new ToolGateway(new ActionValidator(rules, false));
  }

  validate(request: ActionRequest, name: string, rawArgs: unknown): Validation {
    const fail = (code: string) => toolFailure(this.world.locale, code);
    if (!request.allowedTools.includes(name as ToolName) || name === "report_bug") {
      return fail("tool_not_allowed_in_this_turn");
    }
    const tool = name as ToolName;
    const spec = this.specs.get(tool);
    if (!spec || rawArgs === null || typeof rawArgs !== "object" || Array.isArray(rawArgs)) {
      return fail("invalid_tool_arguments");
    }
    // 同一工具只在首个合法参数形态的调用建立 schema；建图失败不先写缓存，后续 properties 仍原位读取。
    let schema = this.schemas.get(tool);
    if (!schema) {
      schema = z.fromJSONSchema(spec.parameters);
      this.schemas.set(tool, schema);
    }
    // 保留原数字字符串修复；不把布尔／文本按 truthiness 或 String() 宽转，也不补缺少的必填参数。
    const wallCall = tool === "write_note" ? readWallTool({ name: tool, args: rawArgs }) : null;
    if (tool === "write_note" && !wallCall) return fail(RuleError.WallNoteText);
    const initialChoice = tool === "choose_thief_card" || tool === "choose_shapeshifter_card";
    const thiefSlot = initialChoice ? readThiefChoice(rawArgs) : undefined;
    if (initialChoice && thiefSlot === undefined)
      return fail(
        tool === "choose_thief_card" ? RuleError.ThiefChoice : RuleError.ShapeshifterChoice,
      );
    if (tool === "choose_admired_player" && !readLonelyGirlTool({ name: tool, args: rawArgs }))
      return fail(RuleError.LonelyGirlChoice);
    const wildCall =
      tool === "choose_wild_model" ? readWildChildTool({ name: tool, args: rawArgs }) : null;
    if (tool === "choose_wild_model" && !wildCall) return fail(RuleError.WildChildChoice);
    const weddingTool =
      [
        "choose_bridegroom",
        "choose_wedding_witness",
        "speak_to_partner",
        "wedding_kill_vote",
      ].includes(tool) ||
      (tool === "kill_vote" && weddingSetup(this.world) !== null);
    const weddingCall = weddingTool ? readWeddingTool({ name: tool, args: rawArgs }) : null;
    if (weddingTool && !weddingCall) return fail(RuleError.GhostBrideChoice);
    const demonCall =
      name === "demon_hunt" ? readDemonHuntTool({ name: tool, args: rawArgs }) : null;
    if (
      name === "demon_hunt" &&
      (!demonCall ||
        !canSubmitDemonHunt(
          this.world,
          request.actorId,
          request.phase,
          request.context.day,
          demonHunterRequestScope(this.world, request),
          demonCall,
        ))
    )
      return fail(RuleError.ToolMismatch);
    const demonNative =
      (tool === "check_identity" || tool === "guard") && demonHunterActorId(this.world) !== null;
    const nativeCall = demonNative ? readDemonNativeNightTool({ name: tool, args: rawArgs }) : null;
    if (
      demonNative &&
      (!nativeCall ||
        !demonWitchRequestCurrent(this.world, request) ||
        (nativeCall.args.target_id !== null &&
          !demonWitchRequestTargetCurrent(this.world, request, nativeCall.args.target_id)))
    )
      return fail(RuleError.ToolMismatch);
    const demonWitch = tool === "use_potion" && demonHunterActorId(this.world) !== null;
    const potionCall = demonWitch ? readDemonPotionTool({ name: tool, args: rawArgs }) : null;
    if (
      demonWitch &&
      (!potionCall ||
        !demonWitchRequestTargetCurrent(this.world, request, potionCall.args.target_id))
    )
      return fail(RuleError.ToolMismatch);
    const input = (
      potionCall
        ? potionCall.args
        : demonCall
          ? demonCall.args
          : weddingCall
            ? weddingCall.args
            : wildCall
              ? wildCall.args
              : initialChoice
                ? { slot: thiefSlot }
                : wallCall
                  ? wallCall.args
                  : { ...rawArgs }
    ) as Record<string, unknown>;
    const properties = spec.parameters.properties as
      Record<string, { type?: string | string[] }> | undefined;
    for (const [key, value] of Object.entries(input)) {
      const type = properties?.[key]?.type;
      const numeric =
        type === "number" ||
        type === "integer" ||
        (Array.isArray(type) && (type.includes("number") || type.includes("integer")));
      if (numeric && typeof value === "string" && /^\d+$/.test(value)) input[key] = Number(value);
    }
    const parsed = schema.safeParse(input);
    if (!parsed.success) return fail("invalid_tool_arguments");
    const args = this.repair.coerceArgs(tool, parsed.data as Record<string, unknown>, {
      actorId: request.actorId,
    });
    if (!args || !schema.safeParse(args).success) return fail("invalid_tool_arguments");
    const call = { name: tool, args } as ToolCall;
    const deathStage =
      DEATH_SHOT_STAGES.includes(request.context.stage) ||
      request.context.stage === "last_words" ||
      request.context.stage === "sheriff_badge_choice";
    const deathTool =
      (tool === "choose_badge_successor" &&
        request.context.stage === "sheriff_badge_choice" &&
        request.context.trigger === "badge_handoff") ||
      (tool === "shoot" &&
        DEATH_SHOT_STAGES.includes(request.context.stage) &&
        request.context.trigger === "on_death") ||
      (tool === "speak" &&
        request.context.stage === "last_words" &&
        request.context.trigger === "last_words");
    if (
      deathStage &&
      (!deathTool ||
        !this.world.hasDeathAction(
          request.actorId,
          tool,
          request.phase,
          request.context.day,
          request.context.death_action_id,
          request.context.ability_id,
        ))
    ) {
      return fail(RuleError.DeathActionUnavailable);
    }
    // 机制 scope 按下面原字段顺序逐个读取；不提前缓存请求许可或绕过 Gateway 的提交前规则。
    const checked = this.gateway.validateAndSanitize(this.world, request.actorId, call, {
      phase: request.phase,
      day: request.context.day,
      thiefScope: thiefRequestScope(this.world, request),
      shapeshifterScope: shapeshifterRequestScope(this.world, request),
      lonelyGirlScope: lonelyGirlRequestScope(this.world, request),
      ghostBrideScope: ghostBrideRequestScope(this.world, request),
      demonHunterScope: demonHunterRequestScope(this.world, request),
      nobleBodyScope: nobleBodyRequestScope(this.world, request),
      fragrantPairScope: fragrantPairRequestScope(this.world, request),
      animalScope: animalRequestScope(this.world, request),
      wildChildScope: wildChildRequestScope(this.world, request),
      wallScope: wallRequestScope(this.world, request),
      wallId: request.context.wall_id,
      itemInstanceId: request.context.item_instance_id,
      debateId: request.context.debate_id,
      abilityId: request.context.ability_id,
      actionWindow: request.actionWindow,
      sheriffCandidates: request.context.sheriff_candidates,
      exileCandidates: request.context.exile_candidates,
      badgeCandidates: request.context.badge_candidates,
      allowSelfDestruct:
        request.allowedTools.includes("self_destruct") ||
        request.allowedTools.includes("self_destruct_with_target"),
      duelWindow: request.context.duel_window,
      allowKnightDuel:
        request.context.stage === request.context.duel_window &&
        request.allowedTools.includes("duel"),
      deathActionId: deathTool ? request.context.death_action_id : undefined,
    });
    if (!checked.ok || !checked.sanitizedCall) {
      return toolFailure(
        this.world.locale,
        checked.error ?? "invalid_tool_arguments",
        checked.message,
      );
    }
    const evaluation = evaluateTurnConstraints(
      { validActions: [checked.sanitizedCall] },
      resolveTurnConstraints(request),
      this.world.locale,
    );
    if (!evaluation.ok) {
      return { ...fail("turn_constraints_not_satisfied"), details: evaluation.errors };
    }
    // 已接受的是脱离的候选，不是领域 commit；库存、租约完成和实际效果仍要在原 owner 重验。
    return { ok: true, action: structuredClone(checked.sanitizedCall) };
  }
}

/** 将已读取的板子覆盖配置合并为规范化的 BoardConfig。 */
import { z } from "zod";
import {
  ActionWindow,
  BoardConfig,
  HookConfig,
  Role,
  WinCondition,
  WitchSelfHealRule,
} from "../../core/domain/model";
import { getDefaultConfigNormalizerRegistry } from "../../game/mechanisms";
import { sixPlayerMvpConfig } from "./six_player_mvp";
import { twelvePlayerStandardConfig } from "./twelve_player_standard";

/** 已支持的板子标识。 */
export type BoardName = "six_player_mvp" | "twelve_player_standard";
type JsonObject = Record<string, unknown>;
export type BoardOverride = Omit<
  Partial<BoardConfig>,
  "hooks" | "sheriff" | "witch" | "tieBreaker" | "selfDestruct"
> & {
  hooks?: Partial<HookConfig>;
  sheriff?: NonNullable<BoardConfig["sheriff"]>;
  witch?: NonNullable<BoardConfig["witch"]>;
  tieBreaker?: NonNullable<BoardConfig["tieBreaker"]>;
  selfDestruct?: NonNullable<BoardConfig["selfDestruct"]>;
};

type StructuredBoardConfig = {
  board?: {
    size?: number;
    roleSetups?: unknown;
  };
  rules?: {
    winCondition?: unknown;
    winConditions?: unknown;
    hooks?: Partial<HookConfig>;
  };
  mechanisms?: {
    sheriff?: {
      enabled?: boolean;
      initialSeat?: number;
      voteWeight?: number;
      tieBreaker?: unknown;
    };
    selfDestruct?: {
      enabledWindows?: unknown;
    };
    tieBreaker?: {
      exileVote?: unknown;
      wolfKillVote?: unknown;
    };
  };
  roles?: {
    witch?: {
      selfHeal?: unknown;
    };
  };
};

const tieBreaker = z.enum(["min_id", "min_seat", "no_elimination", "no_kill"]);
const hooks = z.strictObject({
  onDaybreak: z.boolean().optional(),
  onPreElection: z.boolean().optional(),
  onPreVote: z.boolean().optional(),
  onPerSpeechGap: z.boolean().optional(),
});
const flatOverride = z.strictObject({
  boardSize: z.number().int().positive().optional(),
  enableSheriff: z.boolean().optional(),
  initialSheriffSeat: z.number().int().positive().optional(),
  winCondition: z.enum(WinCondition).optional(),
  winConditions: z.array(z.enum(WinCondition)).optional(),
  hooks: hooks.optional(),
  selfDestruct: z.strictObject({ enabledWindows: z.array(z.enum(ActionWindow)) }).optional(),
  sheriff: z.strictObject({ voteWeight: z.number().positive().optional() }).optional(),
  witch: z.strictObject({ canSelfHeal: z.enum(WitchSelfHealRule).optional() }).optional(),
  tieBreaker: z
    .strictObject({
      exileVote: tieBreaker.optional(),
      wolfKillVote: tieBreaker.optional(),
      sheriffVote: tieBreaker.optional(),
    })
    .optional(),
  roleSetups: z
    .array(z.strictObject({ role: z.enum(Role), count: z.number().int().nonnegative() }))
    .optional(),
});
const structuredOverride = z.strictObject({
  board: z
    .strictObject({
      size: z.number().int().positive().optional(),
      roleSetups: flatOverride.shape.roleSetups,
    })
    .optional(),
  rules: z
    .strictObject({
      winCondition: flatOverride.shape.winCondition,
      winConditions: flatOverride.shape.winConditions,
      hooks: hooks.optional(),
    })
    .optional(),
  mechanisms: z
    .strictObject({
      sheriff: z
        .strictObject({
          enabled: z.boolean().optional(),
          initialSeat: z.number().int().positive().optional(),
          voteWeight: z.number().positive().optional(),
          tieBreaker: tieBreaker.optional(),
        })
        .optional(),
      selfDestruct: z
        .strictObject({ enabledWindows: z.array(z.enum(ActionWindow)).optional() })
        .optional(),
      tieBreaker: z
        .strictObject({ exileVote: tieBreaker.optional(), wolfKillVote: tieBreaker.optional() })
        .optional(),
    })
    .optional(),
  roles: z
    .strictObject({
      witch: z.strictObject({ selfHeal: z.enum(WitchSelfHealRule).optional() }).optional(),
    })
    .optional(),
});

function validateOverride(schema: z.ZodType, value: unknown): void {
  const result = schema.safeParse(value);
  if (!result.success) {
    const field = result.error.issues[0]?.path.join(".") || "document";
    throw new Error(`board_config_invalid_override_field: ${field}`);
  }
}

function isJsonObject(value: unknown): value is JsonObject {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** 克隆基础板子配置，避免后续 merge 污染静态场景常量。 */
function cloneBoardConfig(config: BoardConfig): BoardConfig {
  return {
    ...config,
    roleSetups: config.roleSetups.map((item) => ({ ...item })),
    hooks: { ...config.hooks },
    ...(config.winConditions ? { winConditions: [...config.winConditions] } : {}),
    ...(config.selfDestruct
      ? {
          selfDestruct: {
            enabledWindows: [...config.selfDestruct.enabledWindows],
          },
        }
      : {}),
    ...(config.sheriff ? { sheriff: { ...config.sheriff } } : {}),
    ...(config.witch ? { witch: { ...config.witch } } : {}),
    ...(config.tieBreaker ? { tieBreaker: { ...config.tieBreaker } } : {}),
  };
}

/** 以 BoardConfig 语义合并覆盖项（保留数组/对象的显式拷贝）。 */
function mergeBoardConfig(base: BoardConfig, override: BoardOverride): BoardConfig {
  return {
    ...base,
    ...override,
    hooks: { ...base.hooks, ...(override.hooks ?? {}) },
    roleSetups: override.roleSetups
      ? override.roleSetups.map((item) => ({ ...item }))
      : base.roleSetups.map((item) => ({ ...item })),
    ...(override.winConditions ? { winConditions: [...override.winConditions] } : {}),
    ...(override.selfDestruct
      ? {
          selfDestruct: {
            enabledWindows: [...override.selfDestruct.enabledWindows],
          },
        }
      : base.selfDestruct
        ? {
            selfDestruct: {
              enabledWindows: [...base.selfDestruct.enabledWindows],
            },
          }
        : {}),
    sheriff: { ...(base.sheriff ?? {}), ...(override.sheriff ?? {}) },
    witch: { ...(base.witch ?? {}), ...(override.witch ?? {}) },
    tieBreaker: { ...(base.tieBreaker ?? {}), ...(override.tieBreaker ?? {}) },
  };
}

/** 以“覆盖层”语义合并 default + board 专属配置。 */
function mergeBoardOverride(base: BoardOverride, override: BoardOverride): BoardOverride {
  return {
    ...base,
    ...override,
    ...(base.hooks || override.hooks
      ? {
          hooks: {
            ...(base.hooks ?? {}),
            ...(override.hooks ?? {}),
          },
        }
      : {}),
    ...(base.sheriff || override.sheriff
      ? {
          sheriff: {
            ...(base.sheriff ?? {}),
            ...(override.sheriff ?? {}),
          },
        }
      : {}),
    ...(base.witch || override.witch
      ? {
          witch: {
            ...(base.witch ?? {}),
            ...(override.witch ?? {}),
          },
        }
      : {}),
    ...(base.tieBreaker || override.tieBreaker
      ? {
          tieBreaker: {
            ...(base.tieBreaker ?? {}),
            ...(override.tieBreaker ?? {}),
          },
        }
      : {}),
    ...(override.roleSetups
      ? {
          roleSetups: override.roleSetups.map((item) => ({ ...item })),
        }
      : base.roleSetups
        ? {
            roleSetups: base.roleSetups.map((item) => ({ ...item })),
          }
        : {}),
    ...(override.winConditions
      ? {
          winConditions: [...override.winConditions],
        }
      : base.winConditions
        ? {
            winConditions: [...base.winConditions],
          }
        : {}),
    ...(override.selfDestruct
      ? {
          selfDestruct: {
            enabledWindows: [...override.selfDestruct.enabledWindows],
          },
        }
      : base.selfDestruct
        ? {
            selfDestruct: {
              enabledWindows: [...base.selfDestruct.enabledWindows],
            },
          }
        : {}),
  };
}

/** 读取对应板子的内置默认配置。 */
function baseBoard(board: BoardName): BoardConfig {
  return board === "twelve_player_standard"
    ? cloneBoardConfig(twelvePlayerStandardConfig)
    : cloneBoardConfig(sixPlayerMvpConfig);
}

/** 判断对象是否为旧版平铺结构。 */
function isBoardOverrideShape(value: unknown): value is BoardOverride {
  if (!isJsonObject(value)) {
    return false;
  }
  const keys = Object.keys(value);
  const supported = new Set([
    "boardSize",
    "enableSheriff",
    "initialSheriffSeat",
    "winCondition",
    "winConditions",
    "hooks",
    "selfDestruct",
    "sheriff",
    "witch",
    "tieBreaker",
    "roleSetups",
  ]);
  return keys.some((key) => supported.has(key));
}

/** 判断对象是否为新版结构化配置。 */
function isStructuredBoardOverrideShape(value: unknown): value is StructuredBoardConfig {
  if (!isJsonObject(value)) {
    return false;
  }
  return ["board", "rules", "mechanisms", "roles"].some((key) => key in value);
}

/** 把新版 `board/rules/mechanisms/roles` 结构映射到 BoardConfig 覆盖层。 */
function parseStructuredBoardOverride(raw: StructuredBoardConfig): BoardOverride {
  const out: BoardOverride = {};

  if (isJsonObject(raw.board)) {
    if (typeof raw.board.size === "number") {
      out.boardSize = raw.board.size;
    }
    if (Array.isArray(raw.board.roleSetups)) {
      out.roleSetups = raw.board.roleSetups as BoardConfig["roleSetups"];
    }
  }

  if (isJsonObject(raw.rules)) {
    if (typeof raw.rules.winCondition === "string") {
      out.winCondition = raw.rules.winCondition as BoardConfig["winCondition"];
    }
    if (Array.isArray(raw.rules.winConditions)) {
      out.winConditions = raw.rules.winConditions as BoardConfig["winConditions"];
    }
    if (isJsonObject(raw.rules.hooks)) {
      out.hooks = {
        ...(typeof raw.rules.hooks.onDaybreak === "boolean"
          ? { onDaybreak: raw.rules.hooks.onDaybreak }
          : {}),
        ...(typeof raw.rules.hooks.onPreElection === "boolean"
          ? { onPreElection: raw.rules.hooks.onPreElection }
          : {}),
        ...(typeof raw.rules.hooks.onPreVote === "boolean"
          ? { onPreVote: raw.rules.hooks.onPreVote }
          : {}),
        ...(typeof raw.rules.hooks.onPerSpeechGap === "boolean"
          ? { onPerSpeechGap: raw.rules.hooks.onPerSpeechGap }
          : {}),
      } as HookConfig;
    }
  }

  if (isJsonObject(raw.mechanisms)) {
    if (isJsonObject(raw.mechanisms.sheriff)) {
      if (typeof raw.mechanisms.sheriff.enabled === "boolean") {
        out.enableSheriff = raw.mechanisms.sheriff.enabled;
      }
      if (typeof raw.mechanisms.sheriff.initialSeat === "number") {
        out.initialSheriffSeat = raw.mechanisms.sheriff.initialSeat;
      }
      if (typeof raw.mechanisms.sheriff.voteWeight === "number") {
        out.sheriff = {
          ...(out.sheriff ?? {}),
          voteWeight: raw.mechanisms.sheriff.voteWeight,
        };
      }
      if (typeof raw.mechanisms.sheriff.tieBreaker === "string") {
        // sheriff.tieBreaker 在新结构里归一到 tieBreaker.sheriffVote。
        out.tieBreaker = {
          ...(out.tieBreaker ?? {}),
          sheriffVote: raw.mechanisms.sheriff.tieBreaker as NonNullable<
            BoardConfig["tieBreaker"]
          >["sheriffVote"],
        };
      }
    }
    if (isJsonObject(raw.mechanisms.selfDestruct)) {
      if (Array.isArray(raw.mechanisms.selfDestruct.enabledWindows)) {
        out.selfDestruct = {
          enabledWindows: raw.mechanisms.selfDestruct.enabledWindows as NonNullable<
            BoardConfig["selfDestruct"]
          >["enabledWindows"],
        };
      }
    }
    if (isJsonObject(raw.mechanisms.tieBreaker)) {
      out.tieBreaker = {
        ...(out.tieBreaker ?? {}),
        ...(typeof raw.mechanisms.tieBreaker.exileVote === "string"
          ? {
              exileVote: raw.mechanisms.tieBreaker.exileVote as NonNullable<
                BoardConfig["tieBreaker"]
              >["exileVote"],
            }
          : {}),
        ...(typeof raw.mechanisms.tieBreaker.wolfKillVote === "string"
          ? {
              wolfKillVote: raw.mechanisms.tieBreaker.wolfKillVote as NonNullable<
                BoardConfig["tieBreaker"]
              >["wolfKillVote"],
            }
          : {}),
      };
    }
  }

  if (isJsonObject(raw.roles)) {
    if (isJsonObject(raw.roles.witch) && typeof raw.roles.witch.selfHeal === "string") {
      out.witch = {
        ...(out.witch ?? {}),
        canSelfHeal: raw.roles.witch.selfHeal as NonNullable<BoardConfig["witch"]>["canSelfHeal"],
      };
    }
  }

  return out;
}

/** 统一解析“单个配置块”成覆盖层（兼容新旧两种结构）。 */
function toBoardOverride(value: unknown): BoardOverride | null {
  if (isBoardOverrideShape(value)) {
    validateOverride(flatOverride, value);
    return value as BoardOverride;
  }
  if (isStructuredBoardOverrideShape(value)) {
    validateOverride(structuredOverride, value);
    return parseStructuredBoardOverride(value);
  }
  return null;
}

/** 从 json 根对象提取目标板子的覆盖配置（含 boards/default 合并）。 */
export function parseBoardOverride(raw: unknown, board: BoardName): BoardOverride | null {
  const direct = toBoardOverride(raw);
  if (direct) {
    return direct;
  }
  if (!isJsonObject(raw)) {
    return null;
  }

  if ("boards" in raw || "default" in raw) {
    validateOverride(
      z.strictObject({
        boards: z
          .record(
            z.string().regex(/^[a-z][a-z0-9_-]*$/),
            z.union([flatOverride, structuredOverride]),
          )
          .optional(),
        default: z.union([flatOverride, structuredOverride]).optional(),
      }),
      raw,
    );
  } else {
    const allowed = new Set([board, "six_player_mvp", "twelve_player_standard"]);
    for (const [key, value] of Object.entries(raw)) {
      if (!allowed.has(key)) throw new Error("board_config_invalid_override_field: document");
      validateOverride(z.union([flatOverride, structuredOverride]), value);
    }
  }

  const boardsEntry = isJsonObject(raw.boards) ? raw.boards[board] : undefined;
  const boardOverride = toBoardOverride(boardsEntry);
  if (boardOverride) {
    const defaultOverride = toBoardOverride(raw.default);
    if (!defaultOverride) {
      return boardOverride;
    }
    return mergeBoardOverride(defaultOverride, boardOverride);
  }

  const keyedBoardOverride = toBoardOverride(raw[board]);
  if (keyedBoardOverride) {
    return keyedBoardOverride;
  }
  return null;
}

/** 合并并规范化板子配置；文件查找由加载层负责。 */
export function resolveBoardConfig(
  board: BoardName,
  override: BoardOverride | null = null,
): BoardConfig {
  const base = baseBoard(board);
  const merged = override ? mergeBoardConfig(base, override) : base;
  return getDefaultConfigNormalizerRegistry().normalize(merged);
}
